import React from "react";
import { AuctionDetailView } from "@/components/auctions/AuctionDetailView";

// Auction ids are generated by the mock server at runtime, so this route must
// remain dynamic. Pre-rendering a fixed list made newly created lots unreachable.
export const dynamic = "force-dynamic";

export default function AuctionDetailPage({
  params,
}: {
  params: { auctionId: string };
}) {
  return <AuctionDetailView auctionId={params.auctionId} />;
}
